<?php
namespace App\Http\Controllers;
use App\Mail\LeadMagnetDownload; use App\Models\LeadMagnet; use App\Models\Subscriber; use Illuminate\Http\Request; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Mail;
class LeadMagnetController extends Controller { public function subscribe(Request $request, $id) { if ($request->filled('website')) return redirect()->route('thank.you'); $request->validate(['email'=>'required|email|max:255']); $magnet=LeadMagnet::where('is_active',1)->findOrFail($id); $subscriber = Subscriber::firstOrCreate(['email'=>$request->email],['source'=>'lead_magnet']); if ($subscriber->wasRecentlyCreated) { $apiKey = config('services.brevo.api_key'); $listId = config('services.brevo.list_id'); if ($apiKey && $listId) { try { Http::acceptJson()->withHeaders(['api-key'=>$apiKey])->post('https://api.brevo.com/v3/contacts', ['email'=>$subscriber->email, 'listIds'=>[(int) $listId], 'updateEnabled'=>true])->throw(); } catch (\Throwable $e) { Log::error('Brevo subscriber sync failed.', ['subscriber_id'=>$subscriber->id, 'exception_class'=>$e::class]); } } else { Log::warning('Brevo subscriber sync skipped because configuration is missing.', ['subscriber_id'=>$subscriber->id]); } } try { Mail::to($request->email)->send(new LeadMagnetDownload($magnet)); } catch (\Throwable $e) { Log::error('Lead magnet email failed.', ['lead_magnet_id'=>$magnet->id,'exception_class'=>$e::class]); } return redirect()->route('thank.you')->with('success','Đã gửi link tải tài liệu tới email của bạn.'); } }
